<?php $money=static fn(float $v):string=>'KES '.number_format($v,2);$student=$student??[];$summary=$summary??[];$invoices=$invoices??[];$payments=$payments??[];$from=(string)($_GET['from']??'');$to=(string)($_GET['to']??''); ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Ledger | EduSasa</title><style>body{font-family:system-ui,sans-serif;margin:0;background:#f6f7fb;color:#172033}.wrap{max-width:1200px;margin:32px auto;padding:0 18px}.card{background:#fff;border:1px solid #e6e8ef;border-radius:12px;padding:18px;margin-bottom:16px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}.value{font-size:22px;font-weight:700;margin-top:6px}.muted{color:#667085}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:11px;border-bottom:1px solid #eee;text-align:left}a,.btn{display:inline-block;padding:9px 13px;border-radius:8px;text-decoration:none;background:#172033;color:#fff;border:0}input{padding:9px;border:1px solid #ccd1db;border-radius:8px}.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:end}.negative{font-weight:700}</style></head><body><main class="wrap"><div class="actions"><a href="/finance">← Finance</a><a href="/finance/students/<?= (int)$student['id'] ?>/statement?from=<?= urlencode($from) ?>&to=<?= urlencode($to) ?>">Statement</a></div><section class="card"><h1><?= htmlspecialchars($student['first_name'].' '.$student['last_name']) ?></h1><p class="muted">Admission No: <?= htmlspecialchars($student['admission_no']) ?></p><form class="actions" method="get"><label>From<br><input type="date" name="from" value="<?= htmlspecialchars($from) ?>"></label><label>To<br><input type="date" name="to" value="<?= htmlspecialchars($to) ?>"></label><button class="btn">Filter</button></form></section><section class="grid"><div class="card"><span class="muted">Billed</span><div class="value"><?= $money((float)($summary['billed']??0)) ?></div></div><div class="card"><span class="muted">Paid</span><div class="value"><?= $money((float)($summary['paid']??0)) ?></div></div><div class="card"><span class="muted">Outstanding</span><div class="value negative"><?= $money((float)($summary['outstanding']??0)) ?></div></div><div class="card"><span class="muted">Payments</span><div class="value"><?= (int)($summary['payments']??0) ?></div></div></section><section class="card"><h2>Invoices</h2><table><thead><tr><th>Date</th><th>Invoice</th><th>Item</th><th>Status</th><th>Amount</th></tr></thead><tbody><?php foreach($invoices as $row): ?><tr><td><?= htmlspecialchars($row['invoice_date']) ?></td><td><?= htmlspecialchars($row['invoice_no']) ?></td><td><?= htmlspecialchars($row['description']) ?></td><td><?= htmlspecialchars(ucwords(str_replace('_',' ',$row['status']))) ?></td><td><?= $money((float)$row['amount']) ?></td></tr><?php endforeach;if(!$invoices): ?><tr><td colspan="5" class="muted">No invoices in this period.</td></tr><?php endif; ?></tbody></table></section><section class="card"><h2>Payments & Receipts</h2><table><thead><tr><th>Date</th><th>Receipt</th><th>Method</th><th>Reference</th><th>Amount</th><th>Allocated</th></tr></thead><tbody><?php foreach($payments as $row): ?><tr><td><?= htmlspecialchars($row['payment_date']) ?></td><td><?= htmlspecialchars($row['receipt_no']) ?></td><td><?= htmlspecialchars(strtoupper($row['method'])) ?></td><td><?= htmlspecialchars((string)($row['reference']??'')) ?></td><td><?= $money((float)$row['amount']) ?></td><td><?= $money((float)$row['allocated']) ?></td></tr><?php endforeach;if(!$payments): ?><tr><td colspan="6" class="muted">No payments in this period.</td></tr><?php endif; ?></tbody></table></section></main></body></html>
